fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    let n = condition.len();
    // Preallocate the result vector with capacity n
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        // Select from x if condition[i] is true, else from y
        if condition[i] {
            result.push(x[i]);
        } else {
            result.push(y[i]);
        }
    }

    result
}